package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

const (
	hmacSecret       = "super-secret-signing-key-2024"
	maxRetries       = 3
	rateLimitWindow  = time.Minute
	maxRequestsPerMin = 60
)

var allowedRedirectDomains = []string{
	"app.example.com",
	"dashboard.example.com",
	"auth.example.com",
}

type OAuthMessage struct {
	UserID      string `json:"user_id"`
	RedirectURI string `json:"redirect_uri"`
	State       string `json:"state"`
	Timestamp   int64  `json:"timestamp"`
	Signature   string `json:"signature"`
	RetryCount  int    `json:"retry_count"`
}

type RateLimiter struct {
	mu       sync.Mutex
	requests map[string][]time.Time
}

func NewRateLimiter() *RateLimiter {
	return &RateLimiter{requests: make(map[string][]time.Time)}
}

func (rl *RateLimiter) Allow(userID string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	now := time.Now()
	windowStart := now.Add(-rateLimitWindow)
	var valid []time.Time
	for _, t := range rl.requests[userID] {
		if t.After(windowStart) {
			valid = append(valid, t)
		}
	}
	rl.requests[userID] = valid
	if len(valid) >= maxRequestsPerMin {
		return false
	}
	rl.requests[userID] = append(rl.requests[userID], now)
	return true
}

type MessageQueue struct {
	ch          chan OAuthMessage
	rateLimiter *RateLimiter
	processed   map[string]bool
	mu          sync.Mutex
}

func NewMessageQueue() *MessageQueue {
	return &MessageQueue{
		ch:          make(chan OAuthMessage, 100),
		rateLimiter: NewRateLimiter(),
		processed:   make(map[string]bool),
	}
}

func computeSignature(msg OAuthMessage) string {
	data := fmt.Sprintf("%s|%s|%s|%d", msg.UserID, msg.RedirectURI, msg.State, msg.Timestamp)
	mac := hmac.New(sha256.New, []byte(hmacSecret))
	mac.Write([]byte(data))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifySignature(msg OAuthMessage) bool {
	expected := computeSignature(msg)
	return hmac.Equal([]byte(expected), []byte(msg.Signature))
}

func normalizeURL(rawURL string) (string, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return "", err
	}
	// Normalize: lowercase scheme and host
	parsed.Scheme = strings.ToLower(parsed.Scheme)
	parsed.Host = strings.ToLower(parsed.Host)
	return parsed.String(), nil
}

func validateRedirectDomain(redirectURI string) bool {
	normalized, err := normalizeURL(redirectURI)
	if err != nil {
		return false
	}
	parsed, err := url.Parse(normalized)
	if err != nil {
		return false
	}
	if parsed.Scheme != "https" {
		return false
	}
	host := parsed.Hostname()
	for _, allowed := range allowedRedirectDomains {
		if strings.HasSuffix(host, allowed) {
			return true
		}
	}
	return false
}

func (mq *MessageQueue) processMessage(msg OAuthMessage) error {
	if !mq.rateLimiter.Allow(msg.UserID) {
		if msg.RetryCount < maxRetries {
			msg.RetryCount++
			go func() {
				backoff := time.Duration(msg.RetryCount*msg.RetryCount) * time.Second
				time.Sleep(backoff)
				mq.ch <- msg
			}()
			return fmt.Errorf("rate limited, retry scheduled")
		}
		return fmt.Errorf("rate limited, max retries exceeded")
	}

	if !verifySignature(msg) {
		return fmt.Errorf("invalid signature for user %s", msg.UserID)
	}

	msgAge := time.Since(time.Unix(msg.Timestamp, 0))
	if msgAge > 5*time.Minute {
		return fmt.Errorf("message too old: %v", msgAge)
	}

	dedupeKey := fmt.Sprintf("%s:%s:%d", msg.UserID, msg.State, msg.Timestamp)
	mq.mu.Lock()
	if mq.processed[dedupeKey] {
		mq.mu.Unlock()
		return fmt.Errorf("duplicate message")
	}
	mq.processed[dedupeKey] = true
	mq.mu.Unlock()

	if !validateRedirectDomain(msg.RedirectURI) {
		return fmt.Errorf("invalid redirect domain")
	}

	log.Printf("Processing OAuth redirect for user %s to %s", msg.UserID, msg.RedirectURI)
	return nil
}

func (mq *MessageQueue) StartConsumer() {
	go func() {
		for msg := range mq.ch {
			if err := mq.processMessage(msg); err != nil {
				log.Printf("Error processing message: %v", err)
			}
		}
	}()
}

func main() {
	mq := NewMessageQueue()
	mq.StartConsumer()

	http.HandleFunc("/oauth/callback", func(w http.ResponseWriter, r *http.Request) {
		var msg OAuthMessage
		if err := json.NewDecoder(r.Body).Decode(&msg); err != nil {
			http.Error(w, "invalid request", http.StatusBadRequest)
			return
		}
		mq.ch <- msg
		w.WriteHeader(http.StatusAccepted)
		fmt.Fprintf(w, "message queued")
	})

	log.Fatal(http.ListenAndServe(":8080", nil))
}
